package com.juans.inspeccion.data.remote.sqlserver;

import com.juans.inspeccion.data.remote.sqlserver.DAO;
import com.juans.inspeccion.data.remote.sqlserver.ConnectionException;
import java.util.*;

/** Test SQL transport only: requests are generated by the production builders. */
final class RecordingSql extends DAO {
    final HashMap<String,HashMap<String,String>> schemas=new HashMap<>();
    final ArrayList<ArrayList<String>> batches=new ArrayList<>();
    final ArrayList<String> singles=new ArrayList<>(), reads=new ArrayList<>();
    final ArrayDeque<HashMap<String,String>> rows=new ArrayDeque<>();
    final ArrayList<HashMap<String,String>> details=new ArrayList<>();
    String scalar="4"; boolean fail;
    @Override public void ejecutarComoTransaccion(ArrayList<String> statements) throws ConnectionException {if(fail)throw new ConnectionException("test timeout; commit uncertain");batches.add(new ArrayList<>(statements));}
    @Override public void ejecutarSQL(String statement) throws ConnectionException {if(fail)throw new ConnectionException("test write failure");singles.add(statement);}
    @Override protected HashMap<String,String> columns(String table) { return schemas.get(table); }
    @Override public String consulta_1_Dato(String query) throws ConnectionException {reads.add(query);if(fail)throw new ConnectionException("test read failure");return scalar;}
    @Override public HashMap<String,String> generarHashConConsulta(String query) throws ConnectionException {reads.add(query);if(fail)throw new ConnectionException("test read failure");if(rows.isEmpty())throw new AssertionError("Unexpected query: "+query);return rows.removeFirst();}
    @Override public ArrayList<HashMap<String,String>> generarHashConsultaListaConFechas(HashMap<String,String> schema,String query){reads.add(query);return details;}
}
